package com.eventmanager.controller;
import com.eventmanager.dao.*; import com.eventmanager.model.User; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/admin") public class AdminServlet extends HttpServlet { protected void doPost(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");if(u==null||!"ADMIN".equals(u.role)){res.sendError(403);return;}try{String action=req.getParameter("action");if("approve".equals(action)||"reject".equals(action))new EventDAO().updateStatus(Integer.parseInt(req.getParameter("id")),"approve".equals(action)?"APPROVED":"REJECTED");else if("deleteUser".equals(action))new UserDAO().delete(Integer.parseInt(req.getParameter("id")));res.sendRedirect("dashboard");}catch(Exception e){throw new ServletException(e);}} }
